const {getDatabase}=require('../_db');const {currentUser}=require('./_auth');
module.exports=async function handler(req,res){if(req.method!=='POST')return res.status(405).json({error:'Método não permitido'});const user=currentUser(req);if(!user)return res.status(401).json({error:'Sessão expirada.'});try{const {atendimentoId,texto}=req.body||{};if(!atendimentoId||!String(texto||'').trim())return res.status(400).json({error:'Mensagem vazia.'});const sql=getDatabase();const allowed=await sql`SELECT id,atendente_id FROM atendimentos WHERE id=${atendimentoId} LIMIT 1`;if(!allowed[0])return res.status(404).json({error:'Atendimento não encontrado.'});if(allowed[0].atendente_id!==user.id&&user.perfil!=='ADMINISTRADOR')return res.status(409).json({error:'Assuma ou receba este atendimento antes de responder.'});const rows=await sql`INSERT INTO mensagens (atendimento_id,tipo_remetente,remetente_id,texto) VALUES (${atendimentoId},'ATENDENTE',${user.id},${String(texto).trim()}) RETURNING id,tipo_remetente,remetente_id,texto,criado_em`;await sql`UPDATE atendimentos SET atualizado_em=NOW() WHERE id=${atendimentoId}`;return res.status(200).json({mensagem:rows[0]})}catch(error){console.error(error);return res.status(500).json({error:'Não foi possível enviar a mensagem.'})}};
